import{_ as t,o as s,c as i,a0 as a}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Publish the documentation site","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/publish-docs"},"headers":[],"relativePath":"en/getting-started/publish-docs.md","filePath":"en/getting-started/publish-docs.md"}'),o={name:"en/getting-started/publish-docs.md"};function n(r,e,d,h,c,l){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="publish-the-documentation-site" tabindex="-1">Publish the documentation site <a class="header-anchor" href="#publish-the-documentation-site" aria-label="Permalink to &quot;Publish the documentation site&quot;">​</a></h1><p>The repository Markdown is the only editable source. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/docs/site.json" target="_blank" rel="noreferrer">site manifest</a> decides the published pages; source snippets and the API/configuration references are generated from the implementation. <code>apps/docs/.generated</code> and build output are never committed to source branches.</p><h2 id="registering-bilingual-chapters" tabindex="-1">Registering bilingual chapters <a class="header-anchor" href="#registering-bilingual-chapters" aria-label="Permalink to &quot;Registering bilingual chapters&quot;">​</a></h2><p>The site publishes Simplified Chinese and English side by side: Chinese keeps its existing paths and English lives under the fixed <code>en/</code> prefix, one-to-one with the Chinese chapters. New pages must be delivered as a pair:</p><ol><li>Create a same-named <code>.en.md</code> file next to the Chinese source (for example <code>docs/getting-started/quickstart.md</code> and <code>docs/getting-started/quickstart.en.md</code>). Both files use the same relative links and <code>&lt;&lt;&lt;</code> snippet references; links land on the right language automatically depending on whether the target chapter has an English translation.</li><li>Register one stable <code>id</code> for the page in the <code>pages</code> array of <code>docs/site.json</code>, providing <code>title</code>/<code>titleEn</code> and <code>source</code>/<code>sourceEn</code> together; group names get labels for both languages through the top-level <code>groupLabels</code>.</li><li>Run <code>pnpm docs:check</code>. It validates chapter pairing, duplicate ids/routes, dangling links and the generated references, and fails when an English translation is missing.</li></ol><p>Existing chapters without a translation are explicit migration items: <code>translation: { &quot;status&quot;: &quot;pending&quot;, &quot;owner&quot;: &quot;&lt;ticket&gt;&quot; }</code> declares which implementation ticket will deliver the English page; validation only accepts ticket ids from the published plan. The site keeps building during the migration; these chapters stay out of the English navigation and never generate links to pages that do not exist. Placeholder text must not pretend an English translation exists.</p><p>The language switcher always targets the same chapter; when the target chapter has no English translation it falls back to the English documentation entry. Search covers every published documentation page and generated reference on this site. The whole site shares one top bar, font stack, light/dark theme and language rules; the upcoming Landing, Blog and Downloads pages reuse the same conventions.</p><h2 id="first-time-github-pages-setup" tabindex="-1">First-time GitHub Pages setup <a class="header-anchor" href="#first-time-github-pages-setup" aria-label="Permalink to &quot;First-time GitHub Pages setup&quot;">​</a></h2><p>These steps are for maintainers with repository administration rights. First commit and push the sources to your own GitHub repository, confirm <code>origin</code> points there, and change <code>repository</code> in <code>docs/site.json</code> to your own <code>owner/repository</code>. Source links embed the current commit SHA, so you must rebuild after committing.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p>The publish script commits the static files to a separate <code>gh-pages</code> branch without switching your current source branch or touching the staging area. Then in GitHub&#39;s <strong>Settings → Pages → Build and deployment</strong>, choose <strong>Deploy from a branch</strong>, pick the <code>gh-pages</code> branch with <code>/ (root)</code>, and save. This works for public repositories; other visibility levels depend on your GitHub plan.</p><p>With the GitHub CLI installed and signed in locally, request a build and verify the online result:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>The command checks the Pages configuration, explicitly requests a build, confirms the build corresponds to the static artifact commit that was just published, and reads the online home page to verify the source version. It fails after five minutes; a successful push by itself does not mean the pages are reachable.</p><h2 id="continuous-publishing" tabindex="-1">Continuous publishing <a class="header-anchor" href="#continuous-publishing" aria-label="Permalink to &quot;Continuous publishing&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI workflow</a> runs <code>just check</code> on PRs and stores the documentation artifact. Once sources merge to <code>main</code> and checks pass, the publish job pushes the same artifact to <code>gh-pages</code> and explicitly requests a Pages build using <code>contents: write</code> and <code>pages: write</code> permissions.</p><p>Pushing a branch with the <code>GITHUB_TOKEN</code> in GitHub Actions does not trigger a Pages build, so <code>--request-build</code> cannot be skipped. The first Pages setup still needs an administrator; CI never tries to change repository administration settings.</p><p>The default address is <code>https://&lt;owner&gt;.github.io/&lt;repository&gt;/</code>. The site path is derived from the repository name; custom domains or non-default paths can adjust the build base through <code>DOCS_BASE</code>. Under a subpath deployment, chapter switching, language switching, source links and search are all based on relative paths and the build-time base — no extra configuration required.</p><hr><p>Source version：<code>1983c7865d35</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/docs/getting-started/publish-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,20)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
